(function(){
  const cx=()=>W()/2, cy=()=>H()/2;
  const minR=()=>Math.min(W(),H())*0.24;
  const maxR=()=>Math.min(W(),H())*0.48;
  let t=0;
  const strandData=[];
  const strands=5;
  for(let i=0;i<strands;i++){
    strandData.push({
      phase: Math.random()*Math.PI*2,
      speed: 0.05+Math.random()*0.05,
      turns: 2.2+Math.random()*1.2,
      wobble: 0.06+Math.random()*0.08,
      color: PALETTE[i%PALETTE.length],
      widthBase: 1.1+Math.random()*1.4
    });
  }
  const particles=[];
  const fluffCount=70;
  for(let i=0;i<fluffCount;i++){
    particles.push({
      a: Math.random()*Math.PI*2,
      r: minR()+Math.random()*(maxR()-minR()),
      speed: (Math.random()*0.3+0.05)*(Math.random()<0.5?-1:1),
      size: 1+Math.random()*2.2,
      drift: Math.random()*Math.PI*2,
      alpha: 0.3+Math.random()*0.5,
      colorIdx: i%PALETTE.length
    });
  }
  function drawStrand(s,time){
    ctx.save();
    ctx.translate(cx(),cy());
    ctx.rotate(time*0.02+s.phase*0.1);
    ctx.beginPath();
    const steps=140;
    for(let i=0;i<=steps;i++){
      const p=i/steps;
      const ang=s.phase+p*Math.PI*2*s.turns+time*s.speed;
      const rad=minR()+p*(maxR()-minR())+Math.sin(time*0.6+p*10+s.phase)*s.wobble*30;
      const x=Math.cos(ang)*rad;
      const y=Math.sin(ang)*rad;
      if(i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
    }
    ctx.lineWidth=s.widthBase;
    ctx.strokeStyle=s.color;
    ctx.globalAlpha=0.5;
    ctx.shadowBlur=8;
    ctx.shadowColor=s.color;
    ctx.stroke();
    ctx.restore();
  }
  function frame(){
    t+=0.01;
    ctx.clearRect(0,0,W(),H());
    const grad=ctx.createRadialGradient(cx(),cy(),minR()*0.9,cx(),cy(),maxR()*1.15);
    grad.addColorStop(0,'rgba(0,0,0,0)');
    grad.addColorStop(1,PALETTE[0]+'22');
    ctx.fillStyle=grad;
    ctx.beginPath();
    ctx.arc(cx(),cy(),maxR()*1.2,0,Math.PI*2);
    ctx.fill();
    strandData.forEach(s=>drawStrand(s,t));
    particles.forEach(p=>{
      p.a+=p.speed*0.01;
      const rr=p.r+Math.sin(t*0.5+p.drift)*10;
      const x=cx()+Math.cos(p.a)*rr;
      const y=cy()+Math.sin(p.a)*rr;
      ctx.beginPath();
      ctx.fillStyle=PALETTE[p.colorIdx];
      ctx.globalAlpha=p.alpha*(0.6+0.4*Math.sin(t*2+p.drift));
      ctx.shadowBlur=6;
      ctx.shadowColor=PALETTE[p.colorIdx];
      ctx.arc(x,y,p.size,0,Math.PI*2);
      ctx.fill();
    });
    ctx.globalAlpha=1;
    ctx.shadowBlur=0;
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
})();
